#define MAX_VAL 999999999
#define MAX_VAL_2 999999999999999999LL
#define EPS 1e-6
#define mp make_pair
#define pb push_back

typedef unsigned int UI;
typedef long long int LLI;
typedef unsigned long long int ULLI;
typedef unsigned short int US;
typedef pair<int,int> pii;
typedef pair<LLI,LLI> plli;
typedef vector<int> vi;
typedef vector<LLI> vlli;
typedef vector<pii> vpii;
typedef vector<plli> vplli;

// ---------- END OF TEMPLATE ----------
#define MOD 1000000007

int inv(int n) {
    int e = MOD-2, r = 1;
    while (e > 0) {
        if (e & 1) r = ((LLI) r * n) % MOD;
        e >>= 1;
        n = ((LLI) n * n) % MOD;
    }
    return r;
}

int main() {
    int i, j, k;
    int n;
    scanf("%d", &n);
    int P[6][6];
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) scanf("%d", &P[i][j]);
    }

    int h = (n + 1) / 2;
    int h2 = n - h;
    int inv100 = inv(100);

    // Precompute all masks and their permutations as bitmasks
    vector<int> masks, masks2;
    for (int m = 0; m < (1 << n); m++) {
        int cnt = __builtin_popcount(m);
        if (cnt == h) masks.push_back(m);
        if (cnt == h2) masks2.push_back(m);
    }

    int M = masks.size();
    // Precompute for each mask the list of permutation bitmasks (for first half: columns in mask; for second half: columns not in mask)
    vector<vector<int>> permMasks1(M), permMasks2(M);
    for (int idx = 0; idx < M; idx++) {
        int mask = masks[idx];
        // First half: columns in mask
        vi cols;
        for (k = 0; k < n; k++) if (mask & (1 << k)) cols.push_back(k);
        sort(cols.begin(), cols.end());
        do {
            int pm = 0;
            for (int r = 0; r < (int)cols.size(); r++) pm |= (1 << (r * n + cols[r]));
            permMasks1[idx].push_back(pm);
        } while (next_permutation(cols.begin(), cols.end()));
        // Second half: columns not in mask
        cols.clear();
        for (k = 0; k < n; k++) if (!(mask & (1 << k))) cols.push_back(k);
        sort(cols.begin(), cols.end());
        do {
            int pm = 0;
            for (int r = 0; r < (int)cols.size(); r++) pm |= (1 << (r * n + cols[r]));
            permMasks2[idx].push_back(pm);
        } while (next_permutation(cols.begin(), cols.end()));
    }

    vector<int> prob(1 << M, 0), prob2(1 << M, 0);

    // First half
    int totalEdges1 = n * h;
    for (int state = 0; state < (1 << totalEdges1); state++) {
        LLI p = 1;
        for (int e = 0; e < totalEdges1; e++) {
            int x = e / n, y = e % n;
            if (state & (1 << e))
                p = p * ((LLI)P[x][y] * inv100 % MOD) % MOD;
            else
                p = p * ((LLI)(100 - P[x][y]) * inv100 % MOD) % MOD;
        }
        int poss = 0;
        for (int idx = 0; idx < M; idx++) {
            for (int pm : permMasks1[idx]) {
                if ((state & pm) == pm) {
                    poss |= (1 << idx);
                    break;
                }
            }
        }
        prob[poss] = (prob[poss] + p) % MOD;
    }

    // Second half
    int totalEdges2 = n * h2;
    for (int state = 0; state < (1 << totalEdges2); state++) {
        LLI p = 1;
        for (int e = 0; e < totalEdges2; e++) {
            int x = e / n + h, y = e % n;
            if (state & (1 << e))
                p = p * ((LLI)P[x][y] * inv100 % MOD) % MOD;
            else
                p = p * ((LLI)(100 - P[x][y]) * inv100 % MOD) % MOD;
        }
        int poss = 0;
        for (int idx = 0; idx < M; idx++) {
            for (int pm : permMasks2[idx]) {
                if ((state & pm) == pm) {
                    poss |= (1 << idx);
                    break;
                }
            }
        }
        prob2[poss] = (prob2[poss] + p) % MOD;
    }

    // SOS DP on prob2
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < (1 << M); j++) {
            if (j & (1 << i)) {
                prob2[j] = (prob2[j] + prob2[j ^ (1 << i)]) % MOD;
            }
        }
    }

    LLI ans = 0;
    int fullMask = (1 << M) - 1;
    for (int i = 0; i < (1 << M); i++) {
        ans = (ans + (LLI)prob[i] * prob2[fullMask ^ i]) % MOD;
    }
    printf("%I64d\n", (MOD + 1 - ans) % MOD);

    return 0;
}
